CREATE TABLE big (id BIGINT PRIMARY KEY, category VARCHAR(16), payload VARCHAR(64), embedding VECTOR(16));
COMMIT;
SELECT id FROM big ORDER BY id LIMIT 3;
SELECT id FROM big ORDER BY id DESC LIMIT 3;
SELECT id, L2_DISTANCE(embedding, '[0.34123,0.32751,0.97331,0.58632,0.86518,0.14831,0.40381,0.70976,0.42889,0.43807,0.29924,0.41279,0.92943,0.73409,0.77412,0.28846]') AS d FROM big WHERE category = 'cat3' ORDER BY d LIMIT 3;
-- !stop
SELECT id FROM big ORDER BY id LIMIT 3;
